{
  "name": "clm",
  "version": "0.3.0",
  "description": "Replaces compaction for the main conversation: older turns are folded into a ledger (goal, user instructions, done, to do, open questions, key facts) and the transcript is rewritten to the first request, the ledger and the newest turns that fit.",
  "author": {
    "name": "RanolP"
  },
  "types": "./types/index.d.ts",
  "userConfig": {
    "budget": {
      "type": "number",
      "title": "Token budget",
      "description": "Message tokens allowed before older turns are folded into the ledger; the system prompt and tool schemas are not counted. An integer of at least 2000.",
      "default": 32000
    },
    "tailTarget": {
      "type": "number",
      "title": "Tail target",
      "description": "Tokens the first request, the ledger and the kept newest turns may fill after a fold. 0 means half the budget.",
      "default": 0
    },
    "reserve": {
      "type": "number",
      "title": "Reserve",
      "description": "A fold starts this many tokens before the budget is reached. Must be under the budget. 0 means 2048, or a quarter of a budget under 8192.",
      "default": 0
    },
    "model": {
      "type": "string",
      "title": "Summarizer model",
      "description": "Model that folds the older turns into the ledger.",
      "default": "haiku"
    },
    "reviewModel": {
      "type": "string",
      "title": "Reviewer model",
      "description": "Model that audits each fold's claims against their quotes. Empty means the summarizer model.",
      "default": ""
    }
  }
}

files.types/index.d.ts:
export type ClmBoardIssue = {
  id: string
  title: string
  status: 'todo' | 'doing' | 'done' | 'question' | 'dropped'
  repo: string
  branch?: string
  updated: string
}

export type ClmIssueStatus = ClmBoardIssue['status']

export type ClmIssue = {
  id: string
  title: string
  status: ClmIssueStatus
  updated: string
}

export type ClmTrackInput = {
  title: string
  status: ClmIssueStatus
  issue?: string
}

export type ClmIssueQuery = {
  issue?: string
  status?: ClmIssueStatus
}

export type ClmLaterItem = {
  text: string
  issue?: string
}

export type ClmWorkflow = {
  later: ClmLaterItem[]
  resumeRequest: { text: string } | null
  lastSubmittedTurn: string | null
  activeTurnId: string | null
  promptSeq: number
  focusAppliedSeq: number
  replayed: { issue: string } | null
}

export type ClmStatus = {
  focus: { id: string; title: string; status: 'todo' | 'doing' | 'done' | 'question' | 'uncertain' | 'dropped' } | null
  stackDepth: number
  pending: Array<{ id: string; title: string }>
  agents: Array<{ agentId: string; taskId: string; title: string; status: 'todo' | 'doing' | 'done' | 'question' | 'uncertain' | 'dropped' }>
  later: ClmLaterItem[]
  resumeRequest: { text: string } | null
  lastFoldAt: number | null
  ledgerPath: string
  openIssues: number
}

export type ClmRecallInput = { address: string }
export type ClmTaskInput = {
  id?: string
  title?: string
  status: 'doing' | 'done' | 'uncertain' | 'dropped'
  note?: string
  evidence?: { ref: string; quote: string }
}

export type Clm = {
  /** Create an issue in this session, or set an existing issue's status. */
  track(input: ClmTrackInput): Promise<ClmIssue>
  /** Read this session's issues, optionally filtered by id and status. */
  issues(query?: ClmIssueQuery): Promise<ClmIssue[]>
  /** Queue a continuation prompt for clm's turn-end arbiter. */
  resume(input: { text: string }): Promise<'submitted' | 'queued'>
  /** Read the queue, pending resume request, last fold, ledger path, and open issue count. */
  status(): Promise<ClmStatus>
}

declare module 'claude-code' {
  interface McpToolInputs {
    'mcp__clm__clm_recall': ClmRecallInput
    'mcp__clm__clm_task': ClmTaskInput
  }

  interface PluginState {
    clm: { workflow: ClmWorkflow }
  }

  interface EngineInterface {
    clm: Clm
  }
}
